SELECT 'gongkao', '行文脉络', 'kp-xingce-language-reading-main-idea-structure', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "行文脉络分析"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "剥离血肉，只看骨架。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、剥离无关信息"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "文段中出现的“比如”、“例如”、“据统计”、“某专家说”，统统是辅证材料，绝对不能作为主旨！选项如果只围绕例子里的细节展开，直接排！"}]}]}$$ AS jsonb), NULL, '行文脉络的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "片段阅读", "行文脉络"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_reading_main_idea_structure", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
